  (1, N'Item 01', N'a'),
  (2, N'Item 02', N'b'),
  (3, N'Item 03', N'c'),
  (4, N'Item 04', N'-'),
  (5, N'Item 05', N'd');
EXEC Website.SearchForStockItemsByTags @SearchText = N'[c-a]', @MaximumRowsToReturn = 5;
-- expected document: 
